function PropPowerGrid({ en }) {
  const [sel, setSel] = useState(0);
  const X0 = 44, X1 = 348, Y0 = 18, Y1 = 258;
  const MW = (X1 - X0) / 2, MH = (Y1 - Y0) / 2;
  const g = PROP_STAKE_GRID[sel];
  const COLS = ["#E27069", "#D6B152", "#5FB8A5", C.dim];
  return (
    <div>
      <div style={{ ...DGM_WRAP, display: "flex", justifyContent: "center" }}>
        <svg viewBox="0 0 370 292" style={{ width: "100%", maxWidth: 390 }} role="img" aria-label={en ? "power by interest grid" : "パワー×関心グリッド"}>
          {PROP_GRID_POS.map((q, i) => {
            const on = sel === i;
            const x = X0 + q.x * MW, y = Y0 + (1 - q.y) * MH;
            const label = PROP_STAKE_GRID[i].q[en ? 1 : 0].split("= ")[1] || PROP_STAKE_GRID[i].q[en ? 1 : 0];
            return (
              <g key={i} className="gh-node" onClick={() => setSel(i)} role="button" tabIndex={0}
                onKeyDown={(ev) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); setSel(i); } }}>
                <rect x={x + 3} y={y + 3} width={MW - 6} height={MH - 6} rx="7" fill={on ? COLS[i] : C.surface} fillOpacity={on ? 0.22 : 1} stroke={COLS[i]} strokeWidth={on ? 2.4 : 1.2} />
                <text x={x + MW / 2} y={y + MH / 2 - 4} textAnchor="middle" fill={COLS[i]} fontSize="11.5" fontWeight="800">{label}</text>
                <text x={x + MW / 2} y={y + MH / 2 + 14} textAnchor="middle" fill={C.dim} fontSize="9">{q.who[en ? 1 : 0]}</text>
              </g>
            );
          })}
          <text x={(X0 + X1) / 2} y="280" textAnchor="middle" fill={C.muted} fontSize="10.5" fontWeight="700">{en ? "interest →" : "関心 →"}</text>
          <text x="26" y="12" fill={C.muted} fontSize="10.5" fontWeight="700">{en ? "↑ power" : "↑ パワー"}</text>
          <text x={X0 + MW / 2} y="270" textAnchor="middle" fill={C.dim} fontSize="9">{en ? "low" : "低"}</text>
          <text x={X0 + MW + MW / 2} y="270" textAnchor="middle" fill={C.dim} fontSize="9">{en ? "high" : "高"}</text>
        </svg>
      </div>
      <div style={DGM_HINT}>{en ? "Click a quadrant for how to handle it" : "各象限をクリックすると扱い方が出ます"}</div>
      <div style={{ ...DGM_DETAIL, borderLeftColor: COLS[sel] }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: COLS[sel], marginBottom: 4 }}>{g.q[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65 }}>{g.d[en ? 1 : 0]}</div>
      </div>
    </div>
  );
}
