function TacitCycle({ en }) {
  const [sel, setSel] = useState(0);
  const COLS = [C.teal, C.gold, C.wine, C.dim];
  const TC_SHORT = [["振り返り", "Look-back"], ["共同確認", "Joint check"], ["出力レビュー", "Output review"]];
  const NODES = [
    { cx: 190, cy: 55, i: 0 },
    { cx: 272, cy: 197, i: 1 },
    { cx: 108, cy: 197, i: 2 },
  ];
  const s = TACIT_STEPS[sel];
  return (
    <div>
      <div style={{ ...DGM_WRAP, display: "flex", justifyContent: "center" }}>
        <svg viewBox="0 0 380 296" style={{ width: "100%", maxWidth: 400 }} role="img" aria-label={en ? "3+1 step cycle" : "3+1 Stepのサイクル図"}>
          <defs>
            <marker id="tcArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
              <path d="M 0 0 L 10 5 L 0 10 z" fill={C.muted} />
            </marker>
          </defs>
          <path d="M 234.6 66.1 A 95 95 0 0 1 284.9 153.3" fill="none" stroke={C.muted} strokeWidth="1.6" markerEnd="url(#tcArrow)" />
          <path d="M 240.3 230.6 A 95 95 0 0 1 139.7 230.6" fill="none" stroke={C.muted} strokeWidth="1.6" markerEnd="url(#tcArrow)" />
          <path d="M 95.1 153.3 A 95 95 0 0 1 145.4 66.1" fill="none" stroke={C.muted} strokeWidth="1.6" markerEnd="url(#tcArrow)" />
          <text x="190" y="142" textAnchor="middle" fill={C.text} fontSize="13" fontWeight="800">{en ? "3+ cycles" : "3周以上"}</text>
          <text x="190" y="160" textAnchor="middle" fill={C.dim} fontSize="10.5">{en ? "repeat the loop" : "繰り返す"}</text>
          {NODES.map((n) => {
            const st = TACIT_STEPS[n.i];
            const on = sel === n.i;
            return (
              <g key={n.i} className="gh-node" onClick={() => setSel(n.i)} role="button" tabIndex={0}
                onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setSel(n.i); } }}>
                <circle cx={n.cx} cy={n.cy} r="44" fill={on ? COLS[n.i] : C.surface} stroke={COLS[n.i]} strokeWidth={on ? 2.5 : 1.6} />
                <text x={n.cx} y={n.cy - 8} textAnchor="middle" fill={on ? C.bg : COLS[n.i]} fontSize="11.5" fontWeight="800">{st.n}</text>
                <text x={n.cx} y={n.cy + 8} textAnchor="middle" fill={on ? C.bg : C.text} fontSize="10">{TC_SHORT[n.i][en ? 1 : 0]}</text>
                <text x={n.cx} y={n.cy + 22} textAnchor="middle" fill={on ? C.bg : C.dim} fontSize="8.5">{st.who[en ? 1 : 0]}</text>
              </g>
            );
          })}
          <g className="gh-node" onClick={() => setSel(3)} role="button" tabIndex={0}
            onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setSel(3); } }}>
            <rect x="105" y="252" width="170" height="34" rx="17" fill={sel === 3 ? C.dim : C.surface} stroke={C.dim} strokeWidth="1.4" strokeDasharray="4 3" />
            <text x="190" y="274" textAnchor="middle" fill={sel === 3 ? C.bg : C.muted} fontSize="10.5" fontWeight="700">{en ? "+ Shadowing (as needed)" : "＋ 並走観察（必要に応じて）"}</text>
          </g>
        </svg>
      </div>
      <div style={DGM_HINT}>{en ? "Click a step for detail" : "各ステップをクリックすると詳細が出ます"}</div>
      <div style={DGM_DETAIL}>
        <div style={{ display: "flex", gap: 7, alignItems: "baseline", marginBottom: 4, flexWrap: "wrap" }}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: COLS[sel] }}>{s.n}</span>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: C.text }}>{s.t[en ? 1 : 0]}</span>
          <span style={{ fontSize: 10, fontWeight: 800, color: C.dim, border: `1px solid ${C.line}`, borderRadius: 999, padding: "1px 8px" }}>{s.who[en ? 1 : 0]}</span>
        </div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65 }}>{s.d[en ? 1 : 0]}</div>
      </div>
    </div>
  );
}

const TDIF_LABELS = [["低", "Low"], ["中", "Mid"], ["高", "High"]];
