function ArchStackDiagram({ en, layer: layerProp, onLayer }) {
  const [pat, setPat] = useState(0);
  const [layerLocal, setLayerLocal] = useState("orch");
  // 層の選択は親から渡されればそちらを使う（早見表と同じ層を指すため）
  const layer = layerProp || layerLocal;
  const setLayer = (v) => { setLayerLocal(v); if (onLayer) onLayer(v); };
  const P = ARCH_PATTERNS[pat];
  const G = ARCH_GUIDE[layer];
  const LY = ARCH_LAYERS.find((l) => l.id === layer);
  return (
    <div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
        {ARCH_PATTERNS.map((p, i) => (
          <button key={p.id} onClick={() => setPat(i)}
            style={{ background: pat === i ? C.gold : C.surface, border: `1px solid ${pat === i ? C.gold : C.line}`, color: pat === i ? C.bg : C.text, borderRadius: 999, padding: "4px 11px", fontSize: 11.5, fontWeight: 700, cursor: "pointer" }}>
            {p.t[en ? 1 : 0]}
          </button>
        ))}
      </div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 8 }}>{P.sum[en ? 1 : 0]}</div>
      <div style={{ ...DGM_WRAP, display: "flex", justifyContent: "center" }}>
        <ArchCanvas spec={ARCH_SPECS[P.id]} en={en} sel={layer} onPick={setLayer} label={en ? "architecture diagram" : "アーキテクチャ構成図"} />
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "center", marginBottom: 2 }}>
        {ARCH_LAYERS.map((L) => (
          <span key={L.id} onClick={() => setLayer(L.id)} style={{ cursor: "pointer", fontSize: 9.5, fontWeight: layer === L.id ? 800 : 600, color: layer === L.id ? L.col : C.dim, display: "inline-flex", alignItems: "center", gap: 3 }}>
            <span style={{ width: 8, height: 8, borderRadius: 2, background: L.col, display: "inline-block", opacity: layer === L.id ? 1 : 0.55 }} />{L.t[en ? 1 : 0]}
          </span>
        ))}
      </div>
      <div style={DGM_HINT}>{en ? "Click a layer for its options, the question that decides it, and its trap" : "各層をクリックすると、選択肢・判断を決める問い・落とし穴が出ます"}</div>
      <div style={{ ...DGM_DETAIL, borderLeftColor: LY.col }}>
        <div style={{ fontSize: 12.5, fontWeight: 800, color: LY.col, marginBottom: 5 }}>{LY.t[en ? 1 : 0]}</div>
        <div style={{ fontSize: 11.5, color: C.dim, lineHeight: 1.65, marginBottom: 5 }}>
          {en ? "This pattern uses: " : "この構成での要素: "}<span style={{ color: C.text }}>{(P.nodes[layer] || []).map((x) => thEn(x, en)).join(" / ")}</span>
        </div>
        {G.opts.map((o, i) => (
          <div key={i} style={{ fontSize: 12, color: C.muted, lineHeight: 1.6 }}>▸ {thEn(o, en)}</div>
        ))}
        <div style={{ fontSize: 12, color: C.teal, lineHeight: 1.65, marginTop: 6 }}>❓ {G.q[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, color: "#E27069", lineHeight: 1.65, marginTop: 3 }}>⚠ {G.trap[en ? 1 : 0]}</div>
      </div>
      <div style={{ background: C.surface2, borderRadius: 10, padding: "11px 13px", marginTop: 10 }}>
        <div style={{ fontSize: 12, fontWeight: 800, color: C.text, marginBottom: 4 }}>{en ? "Data flow" : "データの流れ"}</div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7, marginBottom: 8 }}>{P.flow[en ? 1 : 0]}</div>
        <div style={{ fontSize: 12, fontWeight: 800, color: C.text, marginBottom: 4 }}>{en ? "Design points" : "設計のポイント"}</div>
        {P.points.map((p, i) => (
          <div key={i} style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 3 }}>{i + 1}. {p[en ? 1 : 0]}</div>
        ))}
        <div style={{ fontSize: 12, color: "#E08A5E", lineHeight: 1.65, marginTop: 6 }}>
          <span style={{ fontWeight: 800 }}>{en ? "Typical failure " : "典型的な失敗 "}</span>{P.fail[en ? 1 : 0]}
        </div>
      </div>
    </div>
  );
}

