function ArchToolTable({ en, layer, onLayer }) {
  const allCols = [["aws", "AWS"], ["az", "Azure"], ["gc", "Google Cloud"], ["oss", en ? "OSS / other" : "OSS・その他"]];
  const [only, setOnly] = useState(null);           // 1つのクラウドだけを見る
  const cols = only ? allCols.filter(([k]) => k === only) : allCols;
  const chip = (on) => ({ fontSize: 11, padding: "3px 10px", borderRadius: 999, cursor: "pointer", marginRight: 6, marginBottom: 6,
    border: `1px solid ${on ? C.gold : C.line}`, background: "transparent", color: on ? C.gold : C.muted, fontWeight: on ? 700 : 500 });
  return (
    <div>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", marginBottom: 8 }}>
        <span style={{ fontSize: 10.5, color: C.dim, marginRight: 8 }}>{en ? "Show" : "表示するクラウド"}</span>
        <button onClick={() => setOnly(null)} style={chip(!only)}>{en ? "All" : "すべて"}</button>
        {allCols.map(([k, L]) => (
          <button key={k} onClick={() => setOnly(only === k ? null : k)} style={chip(only === k)}>{L}</button>
        ))}
        {layer && (
          <>
            <span style={{ flex: 1 }} />
            <button onClick={() => onLayer && onLayer(null)} style={chip(true)}>
              {en ? "Clear layer highlight" : "層の強調を外す"}
            </button>
          </>
        )}
      </div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, marginBottom: 8 }}>
        {en ? "The same seven layers, with the components that actually show up in builds. Product names move — treat this as a map of the categories, and check the current lineup before quoting it to a client." : "同じ7層に、実際の構成で登場する代表的な要素を並べたもの。製品名と機能名は動くため、これは「カテゴリの地図」として使い、顧客に出す前に各社の現行ラインナップを確認すること。"}
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 680, fontSize: 11 }}>
          <thead><tr>
            <th style={{ textAlign: "left", color: C.dim, padding: "6px 8px", borderBottom: `1px solid ${C.line}`, whiteSpace: "nowrap" }}>{en ? "Layer" : "層"}</th>
            {cols.map(([k, L]) => (
              <th key={k} style={{ textAlign: "left", color: C.dim, padding: "6px 8px", borderBottom: `1px solid ${C.line}` }}>{L}</th>
            ))}
          </tr></thead>
          <tbody>{ARCH_TOOLS.map((r) => {
            const L = ARCH_LAYERS.find((x) => x.id === r.id);
            return (
              <tr key={r.id} onClick={() => onLayer && onLayer(layer === r.id ? null : r.id)}
                  style={{ cursor: onLayer ? "pointer" : "default", background: layer === r.id ? C.surface2 : "transparent", opacity: layer && layer !== r.id ? 0.45 : 1 }}>
                <td style={{ color: L.col, fontWeight: 800, padding: "7px 8px", borderBottom: `1px solid ${layer === r.id ? L.col : C.line}`, verticalAlign: "top", whiteSpace: "nowrap" }}>{L.t[en ? 1 : 0]}</td>
                {cols.map(([k]) => (
                  <td key={k} style={{ color: layer === r.id ? C.text : C.muted, padding: "7px 8px", borderBottom: `1px solid ${layer === r.id ? L.col : C.line}`, lineHeight: 1.55, verticalAlign: "top" }}>{r[k].join(" / ")}</td>
                ))}
              </tr>
            );
          })}</tbody>
        </table>
      </div>
    </div>
  );
}
